WITH ranked AS (SELECT "id", row_number() OVER (ORDER BY "sortOrder", "createdAt", "id") AS position FROM "CoinPackage") UPDATE "CoinPackage" AS packages SET "cardColor" = CASE ((ranked.position - 1) % 8) WHEN 0 THEN 'lilac' WHEN 1 THEN 'coral' WHEN 2 THEN 'mint' WHEN 3 THEN 'blue' WHEN 4 THEN 'pink' WHEN 5 THEN 'amber' WHEN 6 THEN 'teal' ELSE 'peach' END FROM ranked WHERE packages."id" = ranked."id";
